<template>
  <view class="page">
    <view class="mast"><text class="wordmark">净值哨兵</text><text class="version">FUND SENTINEL · 0.1.0</text></view>
    <view v-if="!token" class="card login"><text class="title">让规则，守住你的投资纪律。</text><text class="muted">通过微信登录你的独立监控工作区。</text><button class="primary" :loading="busy" @tap="login">微信登录</button></view>
    <template v-else>
      <view class="tabs"><text v-for="(label,id) in tabs" :key="id" :class="{active:page===id}" @tap="page=id">{{label}}</text></view>
      <view v-if="state.demo" class="warning">当前为合成演示数据，非真实行情。</view>
      <template v-if="page==='dashboard'">
        <view class="hero"><text>总持仓市值</text><text class="total">¥ {{money(total)}}</text><text>{{held.length}} 只持仓基金 · 盘后确认净值</text></view>
        <view class="actions"><button @tap="formOpen=true">手动添加</button><button @tap="scan" :loading="busy">截图导入</button><button @tap="subscribe">续订提醒</button></view>
        <view class="card" v-for="p in state.positions" :key="p.id" @tap="showDetail(p)"><view class="row"><text class="fund">{{state.funds[p.code]?.name}}</text><text>{{p.code}}</text></view><view class="row"><text>{{p.holding?'持仓收益率':'仅自选观察'}}</text><text :class="metric(p).ret>=0?'up':'down'">{{p.holding?metric(p).ret.toFixed(2)+'%':'—'}}</text></view><view class="row"><text>持仓高点回撤</text><text>{{p.holding?metric(p).ddNav.toFixed(2)+'%':'—'}}</text></view><view class="bar"><view :style="{width:Math.min(100,metric(p).ddNav/5*100)+'%'}"/></view><view class="row"><text>基金历史回撤占比</text><text>{{fundMetric(p).reliable?fundMetric(p).ratio.toFixed(1)+'%':'复权待校验'}}</text></view><view class="bar purple"><view :style="{width:Math.min(100,fundMetric(p).ratio)+'%'}"/></view><text class="muted">净值 {{metric(p).date}} · {{p.needsCalibration?'待分红校准':'独立双轨监控'}}</text></view>
        <view v-if="!state.positions.length" class="card"><text>尚无基金，点击手动添加开始监控。</text></view>
      </template>
      <template v-if="page==='strategies'"><button class="primary" @tap="ruleOpen=true">创建规则</button><view class="card" v-for="r in state.rules" :key="r.id"><text class="title">{{RULE_NAMES[r.type]}}</text><text class="muted">{{r.code||'全局默认'}} · 阈值 {{r.threshold}} · 阶梯 {{r.step}}</text><text v-if="r.label">个人标签：{{r.label}}</text><button @tap="toggleRule(r)">{{r.paused?'恢复监控':'暂停规则'}}</button></view></template>
      <template v-if="page==='alerts'"><view class="card" v-for="a in [...state.alerts].reverse()" :key="a.id"><text class="title">{{a.title}}</text><text>{{state.funds[a.code]?.name||'账户组合'}} · {{a.date}}</text><text>指标 {{a.value.toFixed(2)}} / 阈值 {{a.threshold.toFixed(2)}}</text><text v-if="a.label">个人标签：{{a.label}}</text></view><view v-if="!state.alerts.length" class="card">暂无指标触发记录。</view></template>
      <template v-if="page==='settings'"><view class="card"><text class="title">盘后定时监控</text><text>北京时间 21:17 / 22:47 / 08:47</text><text class="muted">自动任务在 GitHub Actions 中运行，须完成云端配置。</text><button @tap="subscribe">授权一次订阅提醒</button><button @tap="refresh">刷新工作区</button><button @tap="logout">退出微信账户</button></view></template>
      <template v-if="page==='detail'&&selected"><view class="card"><text class="title">{{state.funds[selected.code].name}}</text><text>单位净值 {{metric(selected).nav.toFixed(4)}}</text><text>持仓成本 {{selected.cost}} · 最高水位 {{selected.hwm}}</text><text class="muted">上图单位净值；下图复权净值。不同口径独立展示。</text><canvas canvas-id="unitChart" class="chart"/><canvas canvas-id="adjChart" class="chart"/><button @tap="editPosition">编辑 / 分红校准</button><button @tap="resetHwm">重置最高水位线</button><button @tap="page='dashboard'">返回看板</button></view></template>
    </template>
    <view v-if="formOpen" class="overlay"><view class="sheet"><text class="title">确认基金持仓</text><input v-model="form.code" maxlength="6" placeholder="基金 6 位代码（名称请核对）"/><switch :checked="form.holding" @change="form.holding=$event.detail.value"/><text class="muted">开启=真实持仓；关闭=自选观察</text><input v-model="form.shares" type="digit" placeholder="持有份额"/><input v-model="form.cost" type="digit" placeholder="持仓成本单价"/><picker :range="['回溯近60个净值日','仅最新净值','手动最高净值','自建仓日期']" @change="form.peakMode=['60','today','manual','date'][$event.detail.value]"><view class="picker">水位线：{{form.peakMode}}（点击更改）</view></picker><input v-if="form.peakMode==='manual'" v-model="form.manual" type="digit" placeholder="历史最高净值"/><picker v-if="form.peakMode==='date'" mode="date" @change="form.start=$event.detail.value"><view class="picker">建仓日期：{{form.start||'请选择'}}</view></picker><button class="primary" :loading="busy" @tap="savePosition">确认保存</button><button @tap="formOpen=false">取消</button></view></view>
    <view v-if="ocrRecords.length" class="overlay"><view class="sheet"><text class="title">截图字段校验预览</text><view v-for="(r,i) in ocrRecords" :key="i" class="preview"><text>{{r.fund_name||r.fund_code||'未知标的'}}</text><text>成本 {{r.cost_unit??'缺失'}} / 份额 {{r.holding_shares??'缺失'}}</text><text>盈亏 {{r.holding_profit??r.holding_return_pct??'缺失'}}</text><text v-if="!r.is_valid" class="warning">{{r.error_message}}</text><button @tap="confirmOcr(r)">核对与手动补全</button></view><button @tap="ocrRecords=[]">关闭</button></view></view>
    <view v-if="ruleOpen" class="overlay"><view class="sheet"><text class="title">自定义监控规则</text><picker :range="ruleNames" @change="ruleType=RULE_TYPES[$event.detail.value]"><view class="picker">{{RULE_NAMES[ruleType]}}（点击选择）</view></picker><input v-model="threshold" type="digit" placeholder="触发阈值"/><input v-model="activation" type="digit" placeholder="盈利激活门槛 %"/><input v-model="step" type="digit" placeholder="阶梯步长"/><input v-model="label" maxlength="15" placeholder="个人策略标签（15字以内）"/><button class="primary" @tap="saveRule">保存全局规则</button><button @tap="ruleOpen=false">取消</button></view></view>
    <text class="disclaimer">{{DISCLAIMER}}</text>
  </view>
</template>
<script setup>
import {ref,computed,nextTick} from 'vue';
import {onPullDownRefresh} from '@dcloudio/uni-app';
import {API_ORIGIN} from '../../config';
import {emptyWorkspace,positionMetrics,fundMetrics,RULE_NAMES,RULE_TYPES,DISCLAIMER} from '../../../lib/domain';
const token=ref(uni.getStorageSync('fundsentinel-token')||''),state=ref(emptyWorkspace()),busy=ref(false),page=ref('dashboard'),selected=ref(null);
const tabs={dashboard:'全景监控',strategies:'策略规则',alerts:'提醒中心',settings:'设置'};
const formOpen=ref(false),form=ref({code:'',holding:true,shares:'',cost:'',peakMode:'60',manual:'',start:''}),ocrRecords=ref([]);
const ruleOpen=ref(false),ruleType=ref('TRAILING_STOP_NAV'),threshold=ref('5'),activation=ref('5'),step=ref('2'),label=ref(''),ruleNames=RULE_TYPES.map(t=>RULE_NAMES[t]);
const held=computed(()=>state.value.positions.filter(p=>p.holding)),total=computed(()=>held.value.reduce((sum,p)=>sum+metric(p).market,0));
const money=n=>n.toFixed(2),metric=p=>positionMetrics(p,state.value.funds[p.code]),fundMetric=p=>fundMetrics(state.value.funds[p.code]);
const notice=message=>uni.showToast({title:String(message).slice(0,80),icon:'none',duration:4000});
function api(path,data){return new Promise((resolve,reject)=>uni.request({url:API_ORIGIN+'/api/'+path,method:data===undefined?'GET':'POST',header:{Authorization:'Bearer '+token.value,'Content-Type':'application/json'},data,success:r=>{if(r.statusCode===401){token.value='';uni.removeStorageSync('fundsentinel-token');}r.statusCode<300?resolve(r.data):reject(new Error(r.data.error||'操作失败'));},fail:()=>reject(new Error('连接失败，请检查域名配置'))}));}
async function act(fn){busy.value=true;try{await fn();}catch(e){notice(e.message);}finally{busy.value=false;}}
async function login(){await act(async()=>{const wxSession=await uni.login({provider:'weixin'}),session=await api('wechat-login',{code:wxSession.code});token.value=session.access_token;uni.setStorageSync('fundsentinel-token',token.value);uni.setStorageSync('fundsentinel-template',session.templateId);await refresh();});}
async function refresh(){try{state.value=await api('workspace');}catch(e){notice(e.message);}finally{uni.stopPullDownRefresh();}}
function logout(){token.value='';uni.removeStorageSync('fundsentinel-token');state.value=emptyWorkspace();}
async function savePosition(){await act(async()=>{const f=form.value;state.value=await api('positions',{...f,id:f.id||undefined,shares:f.holding?Number(f.shares):undefined,cost:f.holding?Number(f.cost):undefined,manual:f.manual?Number(f.manual):undefined,start:f.start||undefined});formOpen.value=false;notice('持仓已保存');});}
async function saveRule(){await act(async()=>{state.value=await api('rules',{code:null,type:ruleType.value,threshold:Number(threshold.value),activation:Number(activation.value),step:Number(step.value),buffer:1,window:252,basis:'pct',label:label.value,paused:false});ruleOpen.value=false;});}
async function toggleRule(r){await act(async()=>{state.value=await api('rules',{...r,paused:!r.paused});});}
async function subscribe(){const id=uni.getStorageSync('fundsentinel-template');if(!id)return notice('尚未配置订阅模板');uni.requestSubscribeMessage({tmplIds:[id],success:async result=>{if(result[id]==='accept')await act(async()=>{state.value=await api('wechat-subscribe',{});notice('本次订阅授权已记录');});else notice('未授予订阅权限');},fail:()=>notice('订阅授权失败')});}
async function scan(){await act(async()=>{const selection=await uni.chooseImage({count:1,sizeType:['original']}),source=selection.tempFilePaths[0];let output=source,size=Infinity;for(let quality=85;quality>=25;quality-=10){const compressed=await uni.compressImage({src:source,quality,compressedWidth:1280});output=compressed.tempFilePath;size=(await uni.getFileInfo({filePath:output})).size;if(size<500000)break;}if(size>=500000)throw new Error('图片过长，请分段截图');const image=await new Promise((resolve,reject)=>wx.getFileSystemManager().readFile({filePath:output,encoding:'base64',success:r=>resolve('data:image/jpeg;base64,'+r.data),fail:reject}));const result=await api('ocr-preview',{image});ocrRecords.value=result.records;});}
function confirmOcr(r){form.value={code:r.fund_code||'',holding:true,shares:r.holding_shares||'',cost:r.cost_unit||'',peakMode:'60',manual:'',start:''};ocrRecords.value=[];formOpen.value=true;}
function editPosition(){const p=selected.value;form.value={...p,shares:String(p.shares),cost:String(p.cost),peakMode:'60',manual:'',start:''};formOpen.value=true;}
async function resetHwm(){uni.showModal({title:'重置水位线',content:'将最高水位线重置为最新确认净值，重新开始本轮监控？',success:async r=>{if(r.confirm)await act(async()=>{state.value=await api('reset-hwm',{id:selected.value.id});selected.value=state.value.positions.find(p=>p.id===selected.value.id);await drawCharts();});}});}
async function showDetail(p){selected.value=p;page.value='detail';await drawCharts();}
async function drawCharts(){await nextTick();const history=state.value.funds[selected.value.code].history;for(const [id,field]of [['unitChart','nav'],['adjChart','adj']]){const values=history.map(p=>p[field]).filter(v=>v!==null);if(!values.length)continue;const context=uni.createCanvasContext(id),width=300,height=130,min=Math.min(...values),max=Math.max(...values),range=max-min||1;context.setStrokeStyle(field==='nav'?'#3c8864':'#9a86bb');context.setLineWidth(2);context.beginPath();values.forEach((v,i)=>{const x=10+i/(values.length-1||1)*(width-20),y=10+(max-v)/range*(height-20);i?context.lineTo(x,y):context.moveTo(x,y);});context.stroke();context.draw();}}
onPullDownRefresh(refresh);if(token.value)refresh();
</script>
<style scoped>
.page{padding:22px 17px 35px;font-size:13px}.mast{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.wordmark{font-size:23px;font-weight:600}.version{font-size:8px;color:#95a68a;letter-spacing:1px}.tabs{display:flex;justify-content:space-between;margin-bottom:23px;font-size:12px;color:#8d9d80}.tabs text{padding:8px 0}.tabs .active{color:#446d35;border-bottom:2px solid #446d35}.hero{background:#244c33;color:#dce9d0;border-radius:13px;padding:25px;display:flex;flex-direction:column;gap:18px}.hero>text:first-child,.hero>text:last-child{font-size:11px;color:#b3c6a2}.total{font-size:35px}.actions{display:flex;gap:8px;margin:17px 0}.actions button{flex:1;font-size:11px;background:white;color:#628051}.card{background:white;padding:21px;border-radius:11px;border:1px solid #e3eadb;margin:15px 0;display:flex;flex-direction:column;gap:14px}.row{display:flex;justify-content:space-between;gap:13px;font-size:11px}.row .fund{font-size:13px;font-weight:500}.muted{font-size:10px;line-height:1.9;color:#99a68e}.up{color:#c56853}.down{color:#4c8b6e}.bar{height:4px;background:#eef2e7;border-radius:5px;margin-top:-6px;overflow:hidden}.bar>view{height:100%;background:#b1c697}.purple>view{background:#c1add5}.title{font-size:18px;font-weight:500;line-height:1.6}.disclaimer{display:block;font-size:9px;line-height:2;color:#a8b29e;margin-top:25px}.primary{background:#305e3c;color:white;margin-top:15px;width:100%}.overlay{position:fixed;inset:0;background:#14251e99;display:flex;align-items:center;justify-content:center;padding:16px;z-index:10}.sheet{max-height:85vh;overflow:auto;box-sizing:border-box;width:100%;background:white;border-radius:14px;padding:24px;display:flex;flex-direction:column;gap:15px}.sheet input,.picker{background:#f6f8f2;border:1px solid #e2e9d8;border-radius:5px;padding:12px;min-height:22px;font-size:12px}.warning{font-size:11px;color:#b28b4c;background:#fff8e8;padding:12px;line-height:1.8}.preview{display:flex;flex-direction:column;gap:12px;border-bottom:1px solid #e2e9d8;padding-bottom:12px}.chart{width:300px;height:130px;max-width:100%}.login{padding:28px 21px}.card button{font-size:12px;background:#edf3e6;color:#64824f}
</style>
